L = ['# Numbers for the manuscript (generated by scripts/88_paper_numbers.py)', '',
     'Every table below is read from the result files named in its heading; cite these values, not the ones in the reports if they ever disagree. '
     'r = Pearson correlation; CIs are 95 % bootstrap (group/session/game clusters) unless stated. "Within cell" = z-scored within condition x speed (Chirkov), within environment (Wu), within experiment x group size x field (Hawkins).', '']
def tbl(df, title, src, cols=None, nd=3):
    L.append(f'## {title}'); L.append(f'Source: `{src}`'); L.append('')
    d = df if cols is None else df[cols]; d = d.round(nd)
    L.append('| ' + ' | '.join(map(str, d.columns)) + ' |'); L.append('|' + '---|' * len(d.columns))
    for _, r in d.iterrows(): L.append('| ' + ' | '.join('' if (isinstance(v, float) and np.isnan(v)) else str(v) for v in r.values) + ' |')
    L.append('')

