# ---------------- 7. power calculations (recomputed here) ----------------
r = 0.55
def n_for_r(rho, power=0.8, alpha=0.05):
    z = np.arctanh(rho); return int(np.ceil(((stats.norm.ppf(1 - alpha / 2) + stats.norm.ppf(power)) / z) ** 2 + 3))
def n_per_arm(d, power=0.8, alpha=0.05):
    for n in range(2, 10000):
        nc = d * np.sqrt(n / 2); df = 2 * n - 2; crit = stats.t.ppf(1 - alpha / 2, df)
        if 1 - stats.nct.cdf(crit, df, nc) + stats.nct.cdf(-crit, df, nc) >= power: return n
m_half = np.sqrt(2 / np.pi); v_half = 1 - m_half ** 2
# scenario A: existing groups median-split on their members' mean trait (r = 0.55 between group-mean trait and group score)
dA = (r * 2 * m_half) / np.sqrt(1 - r ** 2 * (1 - v_half))
L += ['## 7. Power calculations for a prospective experiment (recomputed by this script; scipy)', 'Assumptions: r = 0.55 between the members\' mean individually-measured trait and the group score (Fig 5); two-sided alpha 0.05, power 0.80.', '',
      f'- Scenario A (median split of groups on their mean trait; the trait distribution of groups is the one observed): expected difference {r * 2 * m_half:.2f} score SD, within-arm SD {np.sqrt(1 - r ** 2 * (1 - v_half)):.2f}, d = {dA:.2f}, n per arm = {n_per_arm(dA)} groups.',
      f'- Scenario B (as A but a weaker true effect, r = 0.40): d = {(0.4 * 2 * m_half) / np.sqrt(1 - 0.16 * (1 - v_half)):.2f}, n per arm = {n_per_arm((0.4 * 2 * m_half) / np.sqrt(1 - 0.16 * (1 - v_half)))} groups.',
      f'- Composition effect: groups needed to detect a correlation of 0.05 / 0.06 / 0.10 / 0.15 at 80 % power: {n_for_r(0.05)} / {n_for_r(0.06)} / {n_for_r(0.10)} / {n_for_r(0.15)}.',
      '- Note: HANDOVER §12 and the HTML summary quote d ~ 1.05 and 15 groups per arm from an earlier (undocumented) calculation; use the values above, which are reproducible.', '']
OUT.write_text('\n'.join(L) + '\n'); print(OUT, len(L), 'lines'); print('\n'.join(L[-8:]))
